// Calculate last 7 days date range
const today = new Date();
const end = today.toISOString().split('T')[0];
const start = new Date(today.setDate(today.getDate() - 7)).toISOString().split('T')[0];
const lastMonth = new Date();
lastMonth.setMonth(lastMonth.getMonth() - 1);
const monthStart = new Date(lastMonth.getFullYear(), lastMonth.getMonth(), 1).toISOString().split('T')[0];
const monthEnd = new Date(lastMonth.getFullYear(), lastMonth.getMonth() + 1, 0).toISOString().split('T')[0];

return [{ json: { week_start: start, week_end: end, month_start: monthStart, month_end: monthEnd } }];

const results = $input.item.json.ResultsByTime || [];
const threshold = $('Config').item.json.COST_ALERT_THRESHOLD;

// Aggregate by service
const serviceMap = {};
let totalCost = 0;

results.forEach(day => {
  (day.Groups || []).forEach(g => {
    const service = g.Keys?.[0] || 'Other';
    const cost = parseFloat(g.Metrics?.BlendedCost?.Amount || '0');
    serviceMap[service] = (serviceMap[service] || 0) + cost;
    totalCost += cost;
  });
});

// Sort by cost descending
const sorted = Object.entries(serviceMap)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 8)
  .map(([svc, cost]) => `${svc}: $${cost.toFixed(2)}`);

const weekStart = $('Build Date Range').item.json.week_start;
const weekEnd = $('Build Date Range').item.json.week_end;

return [{ json: {
  total_cost: totalCost.toFixed(2),
  services_breakdown: sorted.join('\n'),
  week_start: weekStart,
  week_end: weekEnd,
  exceeds_threshold: totalCost > threshold,
  threshold
}}];

